#!/usr/bin/env python3
"""Deterministically bundle Lua modules; no third-party build dependencies."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MODULES = ('xml', 'core', 'ma2', 'ui')

def bundle():
    parts = ['-- Layout Assistant 0.2.0 / grandMA2 3.9 / Lua 5.3\n',
             '-- Generated by tools/build.py. Edit src/, then rebuild.\n',
             'local factories, loaded = {}, {}\n',
             'local function require(name)\n',
             '    if loaded[name] then return loaded[name] end\n',
             '    assert(factories[name], "Unknown bundled module: " .. name)\n',
             '    local result = factories[name]()\n',
             '    loaded[name] = result\n',
             '    return result\nend\n']
    for name in MODULES:
        source = (ROOT / 'src' / f'{name}.lua').read_text(encoding='utf-8')
        parts += [f'factories["layout_assistant.{name}"] = function()\n', source, '\nend\n']
    parts += ['local function main()\n',
              '    local ok, err = pcall(require("layout_assistant.ui").run, gma)\n',
              '    if not ok then gma.feedback("Layout Assistant stopped: " .. tostring(err)) end\n',
              'end\nreturn main\n']
    return ''.join(parts)

if __name__ == '__main__':
    (ROOT / 'dist').mkdir(exist_ok=True)
    (ROOT / 'dist' / 'layout_assistant.lua').write_text(bundle(), encoding='utf-8')
    print('Built dist/layout_assistant.lua')
